param([Parameter(Mandatory=$true)][ValidateSet('smoke','coarse','half')][string]$Window)
# One existing step-candidate reader call only; no adoption, solver, build or next action.
$ErrorActionPreference='Stop';$Window=$Window.ToLowerInvariant();$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$tag='upl_damp_step_CPU_'+$Window+'_r1'
$review=Join-Path $tests ('outputs\'+$tag+'_native');$record=Join-Path $logs ($tag+'.native.json');$callPath=Join-Path $logs ($tag+'_reader.call.json');$log=Join-Path $logs ($tag+'_reader.log')
function E([string]$p){$f=Get-Item -LiteralPath $p -Force;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){
  $seen=@{} # Per-pass only: before/after validation remains independent.
  foreach($e in $rows){
    Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing bound Entry'
    $key=[IO.Path]::GetFullPath([string]$e.path)
    if($seen.ContainsKey($key)){Need ($seen[$key].bytes -eq $e.bytes -and $seen[$key].sha256 -ieq $e.sha256) ('Conflicting duplicate Entry: '+$e.path);continue}
    $a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path);$seen[$key]=$a
  }
}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Save([string]$p,$v){Fresh @($p);[IO.File]::WriteAllText($p,($v|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)))}
function N($v){if($v -is [ValueType]){$n=[double]$v}else{Need (![string]::IsNullOrWhiteSpace([string]$v)) 'Empty number';$n=[double]::Parse([string]$v,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture)};Need (![double]::IsNaN($n) -and ![double]::IsInfinity($n)) 'Nonfinite number';return $n}
Fresh @($review,$record,$callPath,$log);$runPath=Join-Path $logs ($tag+'.run.json');$r=J $runPath;$c=J $r.call.path
Need ($r.passed -and $r.stage -ceq 'upl_damp_step_run_r1' -and $r.backend -ceq 'CPU' -and $r.threads -eq 8 -and $r.window -ceq $Window -and $r.configuration -ceq 'ReleaseCPU' -and $r.public_project_main -and !$r.fixture_or_Run_override -and $r.source_inputs_objects_runtime_canonical_unchanged) 'Own completed CPU8 step-candidate Run required'
Need ($c.direct_native_call -and $c.owned_call_exited -and $c.typed_LASTEXITCODE_captured_immediately -and $c.exit_code -is [int] -and $c.exit_code -eq 0 -and !$c.invocation_failure -and $c.program.sha256 -ceq $r.program.sha256 -and $c.target_program.sha256 -ceq $r.program.sha256) 'Original direct actual typed exit0 required'
$helper=Join-Path $logs 'upl_damp_step_reader_ReleaseCPU_r1.helper.json';$h=J $helper
Need ($h.passed -and $h.stage -ceq 'upl_damp_step_reader_build_r1' -and $h.kind -ceq 'reader' -and $h.configuration -ceq 'ReleaseCPU' -and $h.exact_link_closure_verified -and @($h.objects).Count -eq 85 -and $h.link_object_count -eq 86 -and @($h.runtime).Count -eq 4 -and $h.build_and_source_bindings_unchanged -and !$h.solver_started -and $h.source_build.sha256 -ceq $r.source_build.sha256) 'Current same-source step-candidate reader85+1 authority required'
$dt=[Math]::Pow(2,$(if($Window -ceq 'half'){-19}else{-18}));$fullSteps=if($Window -ceq 'half'){262144}else{131072};$steps=if($Window -ceq 'smoke'){2}else{$fullSteps};$samples=if($Window -ceq 'smoke'){2}else{1341};$end=if($Window -ceq 'smoke'){2*$dt}else{0.5};$drainStep=if($Window -ceq 'half'){5242}else{2621};$postFrames=if($Window -ceq 'smoke'){0}else{1199}
Need ($r.job.expected_samples -eq 1341 -and @($r.job.saved_clock_table).Count -eq 1341 -and $r.job.dt_s -eq $dt -and $r.job.end_s -eq 0.5 -and $r.job.steps -eq $fullSteps -and $r.planned_completed_steps -eq $steps -and $r.planned_end_s -eq $end -and $r.expected_native_frames -eq $samples -and $r.native_frames -eq $samples -and $r.input_window -ceq $(if($Window -ceq 'smoke'){'coarse'}else{$Window})) 'Declared new experiment Run/preset differs'
$clockTable=if($Window -ceq 'smoke'){@([pscustomobject]@{part=0;completed_steps=0;saved_step=0;time_s=0.0},[pscustomobject]@{part=1;completed_steps=2;saved_step=1;time_s=2*$dt})}else{@($r.job.saved_clock_table)}
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_damp_step_run_r1.json')),(E (Join-Path $tests 'notes\upl_damp_step_r1.json')),(E $runPath),$r.call,(E $helper),$h.program,$h.helper_object,$h.compile_call,$h.link_call,$h.compiler_dependency_record,$h.source_build,$h.source_freeze)+@($r.inputs)+@($r.files)+@($h.inputs)+@($h.tools)+@($h.libraries)+@($h.objects)
foreach($p in $h.runtime){$bindings+=@($p.original,$p.copy)};V $bindings
$data=Join-Path (Split-Path -Parent $r.run_out.path) 'data';$argv=@('--read','CPU',$data,$Window,$review);$code=$null;$failure=$null;$started=[DateTime]::UtcNow.ToString('o');[IO.File]::WriteAllBytes($log,[byte[]]@());$saved=$ErrorActionPreference
try{$ErrorActionPreference='Continue';$global:LASTEXITCODE=$null;& $h.program.path @argv 2>&1|Tee-Object -FilePath $log -Append|Out-Host;$code=$LASTEXITCODE}catch{$failure=$_.Exception.Message}finally{$ErrorActionPreference=$saved}
Save $callPath ([ordered]@{program=$h.program;arguments=$argv;started_utc=$started;ended_utc=[DateTime]::UtcNow.ToString('o');direct_native_call=$true;typed_LASTEXITCODE_captured_immediately=($code -is [int]);owned_call_exited=($code -is [int]);exit_code=$code;invocation_failure=$failure;log=(E $log);pure_native_reader=$true;solver_or_build_invoked=$false})
# The real typed reader exit is sealed before checking any exported data.
$done=$null;$completion=$null;$files=@();$unchanged=$false;$historyRows=0;$jsonTimeMax=0.0;$jsonTimeDifferences=0
try{
  Need ($code -is [int] -and $code -eq 0 -and !$failure) 'Reader failed; preserve outputs, never rerun completed solver'
  $completion=E (Join-Path $review 'completion.json');$done=J $completion.path
  Need ($done.passed -and $done.stage -ceq 'upl_damp_step_native_r1' -and $done.backend -ceq 'CPU_public' -and $done.window -ceq $(if($Window -ceq 'smoke'){'smoke'}else{'step500'}) -and $done.preset -ceq $Window -and $done.samples -eq $samples -and $done.native_count -eq 1000 -and $done.fixed_count -eq 40 -and $done.total_native_count -eq 1040 -and $done.physical_columns -eq 26 -and $done.physical_schema -ceq 'case02_common26_col21_ExcessPorePress_NOT_wave26' -and $done.native_total_arrays -eq 22 -and $done.PART_typed_public_metadata_verified -and $done.public_master_on -and $done.no_exclusions -and $done.all_exported_physical_fields_finite -and !$done.physical_acceptance) 'Original typed public22/native1040/finite/schema guards rejected'
  Need ($done.max_ledger_relative_error -le 5e-13 -and $done.soil_ledger_checks -eq (1000*$samples) -and $done.fixed_public_zero_marker_checks -eq (40*$samples) -and $done.dt_s -eq $dt -and [Math]::Abs((N $done.actual_end_s)-$end) -le 1e-14 -and $done.max_noninitial_signed_dterror_s -le 1e-14 -and $done.noninitial_signed_dterror_intervals -eq ($samples-1) -and $done.actual_time_step_locked_dt_exact -and $done.planned_completed_steps -eq $steps -and $done.declared_saved_completed_steps_exact) 'Original ledger/signed necessary-step/end/exact preset guards rejected'
  $history=@(Import-Csv -LiteralPath (Join-Path $review 'history.csv'));$historyRows=$history.Count;Need ($historyRows -eq $samples) 'Native history row count differs';$opened=0
  for($i=0;$i -lt $samples;$i++){
    $row=$history[$i];$step=[long]$row.completed_step;$expected=$clockTable[$i];$savedStep=if($step -gt 0){$step-1}else{0};$wantedTime=[double]$step*$dt;$post=$step -gt $drainStep
    Need ([int]$row.part -eq $i -and [int]$expected.part -eq $i -and $step -eq [long]$expected.completed_steps -and [long]$expected.saved_step -eq $savedStep -and [long]$row.saved_step -eq $savedStep -and [BitConverter]::DoubleToInt64Bits((N $row.time_s)) -eq [BitConverter]::DoubleToInt64Bits($wantedTime) -and [BitConverter]::DoubleToInt64Bits((N $row.dt_s)) -eq [BitConverter]::DoubleToInt64Bits($dt)) 'Actual step-candidate dyadic history schedule differs'
    Need ([int]$row.activeDrainCount -eq $(if($post){10}else{0})) 'Original nonempty true drainage mask differs';$opened+=[int]$post
    $jsonDelta=[Math]::Abs((N $expected.time_s)-$wantedTime);$jsonTimeMax=[Math]::Max($jsonTimeMax,$jsonDelta);if($jsonDelta -ne 0){$jsonTimeDifferences++}
  }
  Need ($opened -eq $postFrames -and $done.post_open_frames -eq $postFrames -and $done.post_open_drained_particle_checks -eq (10*$postFrames) -and $done.max_activeDrainCount -eq $(if($Window -ceq 'smoke'){0}else{10}) -and $done.post_open_completed_step_threshold -eq $drainStep) 'Declared step-candidate post-opening coverage differs'
  $expected=@('original15.bin','physical.bin','clock.bin','common_j_theta.bin','soil_n.bin','native_ids.csv','fixed_ids.csv','history.csv','ledger.csv','fixed_samples.csv','last_poro.csv','columns.csv','completion.json');$leaves=@(Get-ChildItem -LiteralPath $review -File);Need ($leaves.Count -eq 13 -and !(Compare-Object ($leaves.Name|Sort-Object) ($expected|Sort-Object))) 'Native leaf set differs'
}catch{$failure=$_.Exception.Message}
try{V $bindings;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}};if(Test-Path -LiteralPath $review){$files=@(Get-ChildItem -LiteralPath $review -File|Sort-Object Name|ForEach-Object{E $_.FullName})}
$passed=(!$failure -and $unchanged -and $null -ne $done)
Save $record ([ordered]@{stage='upl_damp_step_native_run_r1';passed=[bool]$passed;backend='CPU';window=$Window;source_run=(E $runPath);source_build=$r.source_build;reader_helper=(E $helper);reader_call=(E $callPath);completion=$completion;inputs=$bindings;files=$files;paths=@{native_dir=$review;solver_dir=(Split-Path -Parent $r.run_out.path)};history_rows=$historyRows;original_native_guards_passed=[bool]$passed;drainage_nonempty_per_frame_verified=([bool]$passed -and $Window -cne 'smoke');drainage_check_applicable=($Window -cne 'smoke');bindings_unchanged=$unchanged;reader_executed_by_this_action=$true;adopted_completed_reader=$false;dyadic_schedule_truth='integer completed_steps times locked binary dt; typed C++ exact native-clock guard retained';deserialized_JSON_time_differences_diagnostic=$jsonTimeDifferences;max_deserialized_JSON_time_difference_s_diagnostic=$jsonTimeMax;JSON_text_or_native_clock_modified=$false;reader_rebuilt=$false;solver_or_build_invoked=$false;old_trajectory_prefix_adopted=$false;independent_half_or_cross_performed=$false;physical_acceptance=$false;failure=$failure})
if(!$passed){throw "Step-candidate native review rejected; retain $record and outputs"};Write-Output "One CPU step-candidate native review sealed: $record"
